// @ts-check
// The card catalog shipped with the app (src/core/cardcatalog.json, generated by
// tools/cards/build-catalog.mjs): it parses, and it names standard and service sequences only.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import json from '../src/core/cardcatalog.json' with { type: 'json' };
import { parseCatalog } from '../src/core/cards.js';
import { CATALOG } from '../src/core/catalog.js';

const PRODUCT = /^%(SiemensSeq|AdjustSeq|ServiceSeq)%\\/;

test('the shipped catalog parses (no field outside the schema) and is the one catalog.js exports', () => {
  const parsed = parseCatalog(/** @type {unknown} */ (json));
  assert.ok(parsed.ok, parsed.ok ? '' : parsed.error);
  assert.deepEqual(CATALOG, parsed.catalog);
  assert.ok(CATALOG.cards.length > 0 && CATALOG.sequences.size > 0);
});

test('the shipped catalog names standard and service sequences only', () => {
  for (const seq of CATALOG.sequences.keys()) assert.match(seq, PRODUCT);
  for (const slots of CATALOG.slots.values()) {
    for (const { id, rule } of slots) {
      const bySequence = rule.kind === 'number' ? rule.formatBySequence : rule.kind === 'formula' ? rule.variantBySequence : new Map();
      for (const seq of bySequence.keys()) assert.match(seq, PRODUCT, id);
    }
  }
});
